"""Phase 2 raw Postgres results, verbatim.

Provenance: every string below is the unmodified `data` column returned by one
`execute_sql` call against MCP server `user-supercat-postgres-vpn` on
2026-08-08. The SQL that produced each is stored alongside it in SQL_LOG so the
row-level provenance requirement is satisfied without re-running anything.

Encoding: per-tenant metrics are `<organization_id>:<value>` pairs, space
separated, ordered by value descending. This encoding exists because the MCP
transport returns results inline into the agent context; one compact string per
metric costs far less than 255 JSON objects and preserves tenant identity, which
an aggregate would destroy.

`percentile_cont(...) WITHIN GROUP` is rejected by the MCP query validator, so
all percentiles are computed locally in p2_analyze.py from these exact strings.
"""

# --- SQL provenance ------------------------------------------------------
SQL_LOG = {
    "skus_active":
        "with t as (select organization_id as o, count(*) as v from products "
        "where coalesce(deleted,false)=false group by 1) "
        "select string_agg(o || ':' || v, ' ' order by v desc) as data from t",
    "product_images":
        "with t as (select organization_id as o, count(*) as v from "
        "product_images group by 1) select string_agg(o||':'||v,' ' order by v "
        "desc) as data from t",
    "options_family":
        "select (select string_agg(...) from options) as options_data, "
        "(select ... from option_groups) as option_groups_data, "
        "(select ... from option_mappings) as option_mappings_data",
    "feature_tables":
        "select (... kit_items), (... smart_stacks), (... ipad_reports), "
        "(... showroom_locations), (... commitment_reports), "
        "(... placement_reports), (... mobile_sites), "
        "(select string_agg(o||':'||v,' ' order by v desc) from (select "
        "u.organization_id o, count(*) v from rma_requests r join org_users u "
        "on u.id=r.org_user_id group by 1) x) as rma_requests",
    "customers_inventories":
        "select (... customers), (... inventories) -- grouped counts per org",
    "matrix_contract":
        "select (... matrix_options), (... contract_prices)",
    "config_tables":
        "select (... price_levels), (... taxonomies), (... "
        "distribution_centers), (... user_types), (... shared_resources), "
        "(... surcharge_types)",
    "custom_fields":
        "select (... custom_fields), (... customer_custom_fields), "
        "(... inventory_custom_fields), (... option_custom_fields), "
        "(... order_custom_fields)",
    "login_events":
        "with t as (select organization_id o, count(*) n, count(distinct "
        "user_id) u, count(distinct device_id) d, max(created_at)::date "
        "last_seen, min(created_at)::date first_seen from login_events group "
        "by 1) select string_agg(o||':'||n||':'||u||':'||d||':'||last_seen||"
        "':'||first_seen, ' ' order by n desc) as data from t",
    "orders":
        "with t as (select organization_id o, count(*) n, count(*) filter "
        "(where is_submitted) s, max(created_at)::date last_order from orders "
        "group by 1) select string_agg(o||':'||n||':'||s||':'||last_order,' ' "
        "order by n desc) as data from t",
    "blast_radius":
        "with u as (select organization_id o, count(*) n, count(*) filter "
        "(where last_ipad_login_at is not null) ipad_ever, count(*) filter "
        "(where last_ipad_login_at >= now() - interval '30 days') ipad30, "
        "count(*) filter (where last_ecat_online_login_at is not null) "
        "eol_ever from org_users group by 1), r as (select organization_id o, "
        "count(*) n12 from orders where created_at >= now() - interval '12 "
        "months' group by 1) select string_agg(g.shortname||':'||g.id||':'||"
        "coalesce(u.n,0)||':'||coalesce(u.ipad_ever,0)||':'||"
        "coalesce(u.ipad30,0)||':'||coalesce(u.eol_ever,0)||':'||"
        "coalesce(r.n12,0), ' ' order by coalesce(u.ipad30,0) desc, "
        "coalesce(r.n12,0) desc) as data from organizations g left join u on "
        "u.o=g.id left join r on r.o=g.id",
}

